This is a complete, single-file 3D game called **"Cube Dash"**. It uses **Three.js** for rendering.

In this game, you control a red cube and must dodge incoming blue obstacles. The speed increases as your score goes up!

### How to Play:
1.  Save the code below as an `.html` file (e.g., `game.html`).
2.  Open it in any modern web browser.
3.  **Controls:** Use **Left/Right Arrow Keys** or **A/D Keys** to move.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Cube Dash</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            overflow: hidden;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: #111;
        }

        #ui {
            position: absolute;
            top: 20px;
            left: 20px;
            color: white;
            font-size: 28px;
            font-weight: bold;
            text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.5);
            pointer-events: none;
            z-index: 10;
        }

        #game-over {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: rgba(0, 0, 0, 0.85);
            color: white;
            padding: 30px 50px;
            text-align: center;
            border-radius: 15px;
            display: none;
            box-shadow: 0 0 20px rgba(255, 255, 255, 0.2);
            z-index: 20;
        }

        h1 { margin-top: 0; color: #ff4444; }
        p { font-size: 20px; }

        button {
            background: #4CAF50;
            border: none;
            color: white;
            padding: 12px 24px;
            font-size: 18px;
            cursor: pointer;
            border-radius: 5px;
            transition: background 0.3s;
        }

        button:hover {
            background: #45a049;
        }

        #instructions {
            position: absolute;
            bottom: 20px;
            width: 100%;
            text-align: center;
            color: rgba(255, 255, 255, 0.5);
            font-size: 14px;
            pointer-events: none;
        }
    </style>
</head>
<body>

    <div id="ui">Score: 0</div>

    <div id="game-over">
        <h1>GAME OVER</h1>
        <p id="final-score">Score: 0</p>
        <button onclick="resetGame()">Play Again</button>
    </div>

    <div id="instructions">Use Arrows or A/D to move</div>

    <!-- Use Import Maps to load Three.js easily -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';

        // --- Configuration ---
        const PLAYER_WIDTH = 1;
        const LANE_WIDTH = 10;
        const INITIAL_SPEED = 0.3;
        const SPEED_INCREMENT = 0.0001;
        const OBSTACLE_SPAWN_RATE = 0.8; // Lower is faster spawn frequency

        // --- Game State ---
        let scene, camera, renderer, player;
        let obstacles = [];
        let score = 0;
        let speed = INITIAL_SPEED;
        let gameActive = true;
        let lastSpawnTime = 0;
        let clock = new THREE.Clock();
        let keys = { left: false, right: false };

        init();

        function init() {
            // 1. Scene Setup
            scene = new THREE.Scene();
            scene.background = new THREE.Color(0x1a1a2e);
            scene.fog = new THREE.Fog(0x1a1a2e, 10, 50);

            // 2. Camera Setup
            camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
            camera.position.set(0, 4, 8);
            camera.lookAt(0, 0, 0);

            // 3. Renderer Setup
            renderer = new THREE.WebGLRenderer({ antialias: true });
            renderer.setSize(window.innerWidth, window.innerHeight);
            renderer.setPixelRatio(window.devicePixelRatio);
            document.body.appendChild(renderer.domElement);

            // 4. Lights
            const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
            scene.add(ambientLight);

            const dirLight = new THREE.DirectionalLight(0xffffff, 1);
            dirLight.position.set(5, 10, 5);
            scene.add(dirLight);

            // 5. Floor (Infinite Grid effect)
            const gridHelper = new THREE.GridHelper(100, 50, 0x444444, 0x222222);
            gridHelper.position.y = 0;
            scene.add(gridHelper);

            // 6. Player
            const geometry = new THREE.BoxGeometry(1, 1, 1);
            const material = new THREE.MeshPhongMaterial({ color: 0xff0055, emissive: 0xff0055, emissiveIntensity: 0.5 });
            player = new THREE.Mesh(geometry, material);
            player.position.set(0, 0.5, 0);
            scene.add(player);

            // 7. Input Listeners
            window.addEventListener('keydown', handleKeyDown);
            window.addEventListener('keyup', handleKeyUp);
            window.addEventListener('resize', onWindowResize);

            // Start Loop
            animate();
        }

        function handleKeyDown(e) {
            if (e.key === 'ArrowLeft' || e.key.toLowerCase() === 'a') keys.left = true;
            if (e.key === 'ArrowRight' || e.key.toLowerCase() === 'd') keys.right = true;
        }

        function handleKeyUp(e) {
            if (e.key === 'ArrowLeft' || e.key.toLowerCase() === 'a') keys.left = false;
            if (e.key === 'ArrowRight' || e.key.toLowerCase() === 'd') keys.right = false;
        }

        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        function spawnObstacle() {
            const size = Math.random() * 1.5 + 0.5;
            const geometry = new THREE.BoxGeometry(size, size, size);
            const material = new THREE.MeshPhongMaterial({ 
                color: 0x00d2ff,
                emissive: 0x00d2ff,
                emissiveIntensity: 0.5
            });
            const obstacle = new THREE.Mesh(geometry, material);

            // Random X position within lanes
            const xPos = (Math.random() - 0.5) * LANE_WIDTH;
            obstacle.position.set(xPos, size / 2, -50);

            scene.add(obstacle);
            obstacles.push(obstacle);
        }

        function update() {
            if (!gameActive) return;

            // Movement
            if (keys.left && player.position.x > -LANE_WIDTH/2) {
                player.position.x -= 0.2;
            }
            if (keys.right && player.position.x < LANE_WIDTH/2) {
                player.position.x += 0.2;
            }

            // Speed up over time
            speed += SPEED_INCREMENT;

            // Spawning logic
            const currentTime = clock.getElapsedTime();
            if (currentTime - lastSpawnTime > (OBSTACLE_SPAWN_RATE / (speed * 2))) {
                spawnObstacle();
                lastSpawnTime = currentTime;
            }

            // Update Obstacles
            for (let i = obstacles.length - 1; i >= 0; i--) {
                const obs = obstacles[i];
                obs.position.z += speed;

                // Collision Detection (AABB)
                const playerBox = new THREE.Box3().setFromObject(player);
                const obsBox = new THREE.Box3().setFromObject(obs);

                if (playerBox.intersectsBox(obsBox)) {
                    endGame();
                }

                // Cleanup passed obstacles
                if (obs.position.z > 10) {
                    scene.remove(obs);
                    obstacles.splice(i, 1);
                    score++;
                    document.getElementById('ui').innerText = `Score: ${score}`;
                }
            }
        }

        function endGame() {
            gameActive = false;
            document.getElementById('game-over').style.display = 'block';
            document.getElementById('final-score').innerText = `Final Score: ${score}`;
        }

        // Global function for the button
        window.resetGame = function() {
            // Reset Logic
            score = 0;
            speed = INITIAL_SPEED;
            gameActive = true;
            player.position.set(0, 0.5, 0);
            document.getElementById('ui').innerText = `Score: 0`;
            document.getElementById('game-over').style.display = 'none';

            // Clear obstacles
            obstacles.forEach(obs => scene.remove(obs));
            obstacles = [];

            lastSpawnTime = 0;
            clock.reset();
        };

        function animate() {
            requestAnimationFrame(animate);
            update();
            renderer.render(scene, camera);
        }
    </script>
</body>
</html>
